import pyomo.environ as pyo

DATA = {
    "alloys_on_market": [0, 1],
    "required_elements": ["A", "B"],
    "composition_data": [[0.5, 0.1], [0.5, 0.9]],
    "desired_blend_percentage": [0.5, 0.5],
    "alloy_price": [10.0, 20.0],
    "total_amount": 1.0,
}


def build_model(data=None):
    d = data or DATA

    alloys = d["alloys_on_market"]
    elements = d["required_elements"]

    # Map alloy id -> position in composition_data / alloy_price lists
    alloy_pos = {a: k for k, a in enumerate(alloys)}
    element_pos = {e: k for k, e in enumerate(elements)}

    # composition lookup: composition[i, e]
    composition = {
        (a, e): d["composition_data"][alloy_pos[a]][element_pos[e]]
        for a in alloys
        for e in elements
    }
    price = {a: d["alloy_price"][alloy_pos[a]] for a in alloys}
    desired = {e: d["desired_blend_percentage"][element_pos[e]] for e in elements}

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=alloys, ordered=True)
    model.E = pyo.Set(initialize=elements, ordered=True)

    # Decision: amount of each alloy to purchase (continuous, 0..1)
    model.amount_purchased = pyo.Var(
        model.I, within=pyo.NonNegativeReals, bounds=(0.0, 1.0)
    )

    # Objective: minimize total purchase cost
    def obj_rule(m):
        return sum(price[i] * m.amount_purchased[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint 1: desired blend percentage met for each required element
    def blend_rule(m, e):
        return sum(composition[i, e] * m.amount_purchased[i] for i in m.I) == desired[e]

    model.blend_constraint = pyo.Constraint(model.E, rule=blend_rule)

    # Constraint 2: total amount of alloys purchased equals 1
    def total_rule(m):
        return sum(m.amount_purchased[i] for i in m.I) == d["total_amount"]

    model.total_constraint = pyo.Constraint(rule=total_rule)

    return model


